insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-12-foundation-vary-force',12,'Day 12 · Foundation lab: Vary force',array['u1.lab-accel-vs-force'],true);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-12','day-12-foundation-vary-force','day-12-vary-force',array['f12-control','f12-predict','f12-record','f12-drive','f12-evidence','f12-exit'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-3c','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 12 · Quiz: Force and acceleration","instructions":"Work on your own. Name your system and use units in your reasoning.","questions":[{"kind":"choice","points":1,"prompt":"Which move increases the driving weight while keeping the total moving mass fixed?","options":["Move a weight from the cart onto the hanger","Take a weight off the cart and leave it on the table","Add a new weight from outside","Tilt the track"],"correct_index":0,"guide":"The transferred mass stays within the cart–hanger system.","demand":{"blooms":"Understand","dok":1,"evidence":"Identifies the force control."}},{"kind":"choice","points":1,"prompt":"A 0.040 kg hanger falls near Earth. Use g = 10 N/kg. What is its driving weight?","options":["0.004 N","0.40 N","4.0 N","40 N"],"correct_index":1,"guide":"Weight = 0.040 kg × 10 N/kg = 0.40 N.","demand":{"blooms":"Apply","dok":1,"evidence":"Converts hanging mass to driving weight."}},{"kind":"choice","points":1,"prompt":"Two equal masses start at rest. One experiences three times the net force of the other. How do the accelerations compare?","options":["They are equal","The first is one-third as large","The first is three times as large","Both are zero"],"correct_index":2,"guide":"At fixed mass, acceleration is proportional to net force.","demand":{"blooms":"Apply","dok":2,"evidence":"Uses direct proportionality."}},{"kind":"choice","points":1,"prompt":"The slope of acceleration versus net force is 4.0 (m/s²)/N. What is the system mass?","options":["4.0 kg","2.0 kg","1.0 kg","0.25 kg"],"correct_index":3,"guide":"Slope = 1/M, so M = 1/4.0 kg.","demand":{"blooms":"Apply","dok":2,"evidence":"Interprets slope with units."}},{"kind":"written","points":3,"prompt":"Two trials at fixed total mass have driving weights 0.20 N and 0.40 N. Their accelerations are 0.18 and 0.37 m/s². Compare the ratios. What supports the ideal trend? Why would you avoid claiming an exact law from these two points alone?","guide":"Weight doubles; acceleration grows by about 2.06. This supports a rising, near-proportional trend over this range. Driving weight can differ from net force; repeated trials, resistance and measurement uncertainty matter.","demand":{"blooms":"Evaluate","dok":3,"evidence":"Tests the trend with quantitative evidence and a limitation."}},{"kind":"written","points":3,"prompt":"A team adds new weights from a shelf to a hanger while leaving the cart alone. They say the whole system has constant mass and hanger weight equals the tension on the cart. Check both statements and describe a fairer test.","guide":"External weights increase total moving mass. Tension can differ from hanger weight while the hanger accelerates. Transfer existing cart weights onto the hanger, keep the setup and release fixed, repeat and compare slopes.","demand":{"blooms":"Analyze","dok":2,"evidence":"Checks the system boundary and force source."}}]}'::jsonb);
